<?php ui_header('Đơn ứng tuyển','Theo dõi hành trình ứng tuyển và kết quả đánh giá CV của bạn.');$labels=['APPLIED'=>'Đã ứng tuyển','AI_SCREENING'=>'AI đang đánh giá','HR_REVIEW'=>'HR xem xét','INTERVIEW'=>'Phỏng vấn','OFFER'=>'Đề nghị']; ?>
<div class="stat-cards section"><?php foreach($labels as $status=>$label): ?><div class="panel"><span class="muted"><?= e($label) ?></span><strong><?= count(array_filter($data,function($a)use($status){return $a['status']===$status;})) ?></strong></div><?php endforeach; ?></div>
<?php if($user['role']!=='CANDIDATE'): ?><a href="/recruiter/dashboard">Xem hồ sơ theo tin tuyển dụng →</a><?php elseif(!$data): ?><section class="panel empty"><h2>Bạn chưa có đơn ứng tuyển nào</h2><p class="muted">Tìm công việc phù hợp và bắt đầu hành trình của bạn.</p><a class="button" href="/jobs">Khám phá việc làm</a></section><?php endif; ?>
<?php foreach($data as $a): ?><article class="panel application-card section"><div class="company-initial"><?= e(mb_substr($a['job']['company']['name'],0,2)) ?></div><div class="application-body"><h2><a href="/applications/<?= e($a['id']) ?>"><?= e($a['job']['title']) ?></a></h2><p class="muted"><?= e($a['job']['company']['name']) ?> · <?= e($a['job']['location']??'Linh hoạt') ?></p><small class="muted">Đã ứng tuyển <?= e(date('d/m/Y',strtotime($a['appliedAt']))) ?></small></div><div><span class="badge"><?= e($labels[$a['status']]??$a['status']) ?></span><p class="positive"><?= $a['aiResult']?'Điểm AI: '.e($a['aiResult']['overallScore']).'/100':'Đang chờ đánh giá CV' ?></p><a class="button ghost" href="/applications/<?= e($a['id']) ?>">Xem chi tiết <?= ui_icon('arrow-right',16) ?></a></div></article><?php endforeach; ?>
